// One-off: pushes the schema to a remote libSQL/Turso DB by executing the
// SQL statements generated by `prisma migrate diff`.
// Reads DATABASE_URL and DATABASE_AUTH_TOKEN from env.

import { createClient } from "@libsql/client";

const url = process.env.DATABASE_URL;
const authToken = process.env.DATABASE_AUTH_TOKEN;

if (!url || !authToken) {
  console.error("Missing DATABASE_URL or DATABASE_AUTH_TOKEN env vars.");
  process.exit(1);
}

const client = createClient({ url, authToken });

const statements = [
  `CREATE TABLE IF NOT EXISTS "User" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "email" TEXT NOT NULL,
    "passwordHash" TEXT NOT NULL,
    "role" TEXT NOT NULL DEFAULT 'USER',
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
  )`,
  `CREATE TABLE IF NOT EXISTS "Phase" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "order" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "eyebrow" TEXT NOT NULL,
    "lore" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'PENDING',
    "closesAt" DATETIME
  )`,
  `CREATE TABLE IF NOT EXISTS "Option" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "phaseId" TEXT NOT NULL,
    "slotId" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "kind" TEXT NOT NULL,
    "lore" TEXT NOT NULL,
    "flavor" TEXT NOT NULL,
    "order" INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT "Option_phaseId_fkey" FOREIGN KEY ("phaseId") REFERENCES "Phase" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
  )`,
  `CREATE TABLE IF NOT EXISTS "Vote" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" TEXT NOT NULL,
    "phaseId" TEXT NOT NULL,
    "optionId" TEXT NOT NULL,
    CONSTRAINT "Vote_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "Vote_phaseId_fkey" FOREIGN KEY ("phaseId") REFERENCES "Phase" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "Vote_optionId_fkey" FOREIGN KEY ("optionId") REFERENCES "Option" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
  )`,
  `CREATE TABLE IF NOT EXISTS "Setting" (
    "key" TEXT NOT NULL PRIMARY KEY,
    "value" TEXT NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS "ImageSlot" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "url" TEXT NOT NULL
  )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS "User_email_key" ON "User"("email")`,
  `CREATE UNIQUE INDEX IF NOT EXISTS "Phase_order_key" ON "Phase"("order")`,
  `CREATE UNIQUE INDEX IF NOT EXISTS "Vote_userId_phaseId_key" ON "Vote"("userId", "phaseId")`,
];

for (const sql of statements) {
  const preview = sql.split("\n")[0].slice(0, 60);
  process.stdout.write(`> ${preview}... `);
  try {
    await client.execute(sql);
    console.log("ok");
  } catch (err) {
    console.log("FAIL");
    console.error(err);
    process.exit(1);
  }
}

const tables = await client.execute(
  `SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '_litestream%' ORDER BY name`
);
console.log("\nTablas existentes en Turso:");
for (const row of tables.rows) {
  console.log(`  - ${row.name}`);
}

client.close();
console.log("\n✓ Schema aplicado correctamente a Turso.");
